#!/usr/bin/env node
/**
 * kvn — Kavanah API client for Claude Code sessions.
 *
 * Zero dependencies on purpose: this runs from ~/.claude/skills/kavanah in any
 * directory, including ones with no node_modules. Everything it knows about the
 * API comes from ../commands.json, regenerated by `npm run skill:gen` in the
 * Kavanah repo.
 *
 * Usage:
 *   kvn <command> [pathParams...] [--field value] [--data '{...}'] [flags]
 *   kvn ls [pattern]              list commands matching a substring/regex
 *   kvn groups                    list command groups
 *   kvn help <command>            full detail for one command
 *   kvn call <METHOD> <path>      escape hatch for anything not in the index
 *   kvn login                     sign in through the browser and save an API key
 *   kvn logout [--keep-key]       revoke and forget the saved key for this base
 *   kvn whoami                    who the current API key authenticates as
 *
 * Flags:
 *   --data, -d <json|@file|->     request body (merged under --field values);
 *                                 `-` reads stdin (a redirected file is read
 *                                 automatically; a pipe needs `--data -`)
 *   --query k=v                   force a query param
 *   --local                       target http://localhost:3000
 *   --base <url>                  target an explicit origin
 *   --key <kvn_live_…>            override the API key
 *   --yes                         confirm a destructive command
 *   --raw                         print the response body verbatim
 *   --include, -i                 print status + response headers to stderr
 *   --dry-run                     print the request without sending it
 */
import { chmodSync, existsSync, fstatSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { homedir, hostname } from "node:os";
import { spawn } from "node:child_process";

const SKILL_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
const DEFAULT_BASE = "https://kavanah.ai";
const LOCAL_BASE = "http://localhost:3000";
const TIMEOUT_MS = Number(process.env.KAVANAH_TIMEOUT_MS ?? 60_000);

// ── index ────────────────────────────────────────────────────────────────────

let INDEX;
function index() {
  if (!INDEX) {
    const file = join(SKILL_DIR, "commands.json");
    if (!existsSync(file)) die(`commands.json missing at ${file} — run 'npm run skill:gen' in the Kavanah repo`);
    INDEX = JSON.parse(readFileSync(file, "utf8"));
    INDEX.byName = new Map(INDEX.commands.map((c) => [c.name, c]));
  }
  return INDEX;
}

// ── credentials ──────────────────────────────────────────────────────────────

const KAVANAH_HOME = join(homedir(), ".kavanah");
const CREDENTIALS_FILE = join(KAVANAH_HOME, "credentials.json");

/** `kvn login` writes one entry per base URL, so a --local login never replaces the production key. */
function readCredentials() {
  try {
    return JSON.parse(readFileSync(CREDENTIALS_FILE, "utf8"));
  } catch {
    return {};
  }
}

function writeCredentials(creds) {
  mkdirSync(KAVANAH_HOME, { recursive: true, mode: 0o700 });
  writeFileSync(CREDENTIALS_FILE, `${JSON.stringify(creds, null, 2)}\n`, { mode: 0o600 });
  chmodSync(CREDENTIALS_FILE, 0o600);
}

/**
 * Key resolution, most explicit first. The .env.local hop is what makes this
 * work with zero setup inside the Kavanah repo itself.
 */
function resolveKey(explicit, base) {
  if (explicit) return explicit;
  if (process.env.KAVANAH_API_KEY) return process.env.KAVANAH_API_KEY;

  const saved = base ? readCredentials()[base]?.token : null;
  if (saved) return saved;

  const keyFile = join(KAVANAH_HOME, "api-key");
  if (existsSync(keyFile)) {
    const val = readFileSync(keyFile, "utf8").trim();
    if (val) return val;
  }
  for (const envFile of [".env.local", ".env"]) {
    const p = join(process.cwd(), envFile);
    if (!existsSync(p)) continue;
    const m = readFileSync(p, "utf8").match(/^\s*KAVANAH_API_KEY\s*=\s*["']?([^"'\s#]+)/m);
    if (m) return m[1];
  }
  return null;
}

function requireKey(explicit, base) {
  const key = resolveKey(explicit, base);
  if (key) return key;
  die(
    [
      "No Kavanah API key found.",
      "",
      "Easiest: run `kvn login` — it opens the browser, a workspace admin approves,",
      "and the key is saved to ~/.kavanah/credentials.json.",
      "",
      "Or mint one as a workspace admin at Settings → API keys and provide it:",
      "",
      "  export KAVANAH_API_KEY=kvn_live_…          (this shell)",
      "  echo kvn_live_… > ~/.kavanah/api-key       (persistent, all sessions)",
      "  KAVANAH_API_KEY=kvn_live_… in .env.local   (inside the Kavanah repo)",
      "  kvn <command> --key kvn_live_…             (one-off)",
    ].join("\n"),
  );
}

// ── arg parsing ──────────────────────────────────────────────────────────────

// `q` is deliberately NOT here: several routes take a query param literally
// named `q` (search), and claiming it globally made `--q task` unusable.
const GLOBAL_VALUE_FLAGS = new Set(["data", "d", "base", "key", "query"]);
const GLOBAL_BOOL_FLAGS = new Set(["local", "yes", "y", "raw", "dry-run", "include", "i", "help", "h"]);

/**
 * Splits argv into positionals, global flags and per-request fields. A field
 * flag with no following value is `true` (so `--includeArchived` works); a
 * bare `--` stops flag parsing entirely.
 */
function parseArgs(argv) {
  const positional = [];
  const globals = {};
  const fields = new Map(); // name → coerced value (insertion-ordered)
  const forcedQuery = new Map();

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--") {
      positional.push(...argv.slice(i + 1));
      break;
    }
    if (!arg.startsWith("--") && !(arg.startsWith("-") && arg.length === 2 && /[a-z]/i.test(arg[1]))) {
      positional.push(arg);
      continue;
    }

    const isShort = !arg.startsWith("--");
    let name = isShort ? arg.slice(1) : arg.slice(2);
    let inlineValue;
    const eq = name.indexOf("=");
    if (eq !== -1) {
      inlineValue = name.slice(eq + 1);
      name = name.slice(0, eq);
    }

    if (GLOBAL_BOOL_FLAGS.has(name) && inlineValue === undefined) {
      globals[name] = true;
      continue;
    }
    const value = inlineValue !== undefined ? inlineValue : argv[++i];

    if (GLOBAL_VALUE_FLAGS.has(name)) {
      if (value === undefined) die(`--${name} needs a value`);
      if (name === "query") {
        const idx = value.indexOf("=");
        if (idx === -1) die(`--query expects k=v, got "${value}"`);
        forcedQuery.set(value.slice(0, idx), value.slice(idx + 1));
      } else {
        globals[name === "d" ? "data" : name] = value;
      }
      continue;
    }

    // Raw strings are kept here and coerced later against the declared schema
    // type — coercing now would turn `--projectRef 1` into the number 1 for a
    // field the API declares as a string.
    const consumedNextFlag = value !== undefined && value.startsWith("--");
    const bare = value === undefined || consumedNextFlag;
    if (consumedNextFlag) i--; // hand the next flag back to the loop
    fields.set(name, { raw: bare ? "true" : value, bare });
  }

  return { positional, globals, fields, forcedQuery };
}

/**
 * Coerce against the declared OpenAPI type when there is one. `string` is the
 * load-bearing case: several Kavanah fields (projectRef, status_id, tag) are
 * numeric-looking strings, and sending them as JSON numbers fails validation.
 */
function coerceTyped(raw, declaredType) {
  if (!declaredType) return coerce(raw);
  const t = declaredType.toLowerCase();
  if (t.startsWith("string") && !t.includes("[]") && !t.includes("|")) return raw;
  if (t.startsWith("boolean")) return raw === "true" || raw === "1";
  if (t.startsWith("integer") || t.startsWith("number")) {
    const n = Number(raw);
    return Number.isNaN(n) ? raw : n;
  }
  return coerce(raw);
}

/** JSON-ish coercion so `--priority High` stays a string but `--limit 5` is a number. */
function coerce(raw) {
  if (raw === "true") return true;
  if (raw === "false") return false;
  if (raw === "null") return null;
  if (/^-?\d+(\.\d+)?$/.test(raw)) return Number(raw);
  if (/^[[{]/.test(raw)) {
    try {
      return JSON.parse(raw);
    } catch {
      return raw;
    }
  }
  return raw;
}

/** `a.b.c` → nested object assignment, so `--metadata.source cli` works. */
function assignDeep(target, dotted, value) {
  const parts = dotted.split(".");
  let cur = target;
  for (let i = 0; i < parts.length - 1; i++) {
    if (typeof cur[parts[i]] !== "object" || cur[parts[i]] === null) cur[parts[i]] = {};
    cur = cur[parts[i]];
  }
  cur[parts[parts.length - 1]] = value;
}

// ── output ───────────────────────────────────────────────────────────────────

function die(msg, code = 1) {
  process.stderr.write(`${msg}\n`);
  process.exit(code);
}

function out(text) {
  process.stdout.write(text.endsWith("\n") ? text : `${text}\n`);
}

// Piping into `head` closes stdout early; without this every truncated listing
// crashes with an unhandled EPIPE.
for (const stream of [process.stdout, process.stderr]) {
  stream.on("error", (err) => {
    if (err.code === "EPIPE") process.exit(0);
    throw err;
  });
}

// ── subcommands ──────────────────────────────────────────────────────────────

function cmdLs(pattern) {
  const { commands } = index();
  let match = () => true;
  if (pattern) {
    let re;
    try {
      re = new RegExp(pattern, "i");
    } catch {
      re = null;
    }
    const words = pattern.toLowerCase().split(/\s+/).filter(Boolean);
    match = (c) => {
      const hay = `${c.name} ${c.method} ${c.path} ${c.summary} ${c.group}`;
      // Test the name on its own first: anchored patterns like `^tasks\.list$`
      // never match the concatenated haystack, which made every anchored
      // search silently return nothing. Multi-word input matches all words
      // anywhere rather than as one contiguous substring.
      if (re?.test(c.name)) return true;
      const lowered = hay.toLowerCase();
      return words.every((w) => lowered.includes(w));
    };
  }
  const hits = commands.filter(match);
  if (!hits.length) return out(`no commands match "${pattern}"`);
  const width = Math.max(...hits.map((c) => c.name.length));
  for (const c of hits) {
    out(`${c.name.padEnd(width)}  ${c.method.padEnd(6)} ${c.path}${c.summary ? `  — ${c.summary}` : ""}`);
  }
  process.stderr.write(`\n${hits.length} of ${commands.length} commands\n`);
}

/**
 * Suggest alternatives for a miss by walking the dotted name back one segment
 * at a time — `tasks.frobnicate` has no fuzzy neighbours, but `tasks` does.
 */
function suggest(name) {
  const parts = name.split(".");
  for (let i = parts.length; i > 0; i--) {
    const prefix = parts.slice(0, i).join(".");
    const hits = index().commands.filter((c) => c.name.startsWith(prefix));
    if (hits.length) {
      const width = Math.max(...hits.map((c) => c.name.length));
      for (const c of hits.slice(0, 25)) {
        out(`${c.name.padEnd(width)}  ${c.method.padEnd(6)} ${c.path}${c.summary ? `  — ${c.summary}` : ""}`);
      }
      if (hits.length > 25) process.stderr.write(`… and ${hits.length - 25} more — narrow with: kvn ls ${prefix}\n`);
      return;
    }
  }
  process.stderr.write(`nothing similar — try: kvn ls ${parts[0]}\n`);
}

function cmdGroups() {
  const counts = new Map();
  for (const c of index().commands) counts.set(c.group, (counts.get(c.group) ?? 0) + 1);
  for (const [g, n] of [...counts].sort((a, b) => b[1] - a[1])) out(`${String(n).padStart(4)}  ${g}`);
}

function cmdHelp(name) {
  if (!name) return out(readFileSync(new URL(import.meta.url)).toString().split("\n").slice(1, 30).join("\n"));
  const cmd = index().byName.get(name);
  if (!cmd) {
    process.stderr.write(`unknown command "${name}" — closest matches:\n`);
    return cmdLs(name.split(".")[0]);
  }
  const lines = [`${cmd.name}`, `${cmd.method} ${cmd.path}`, `group: ${cmd.group}  source: ${cmd.source}`];
  if (cmd.summary) lines.push("", cmd.summary);
  if (cmd.description && cmd.description !== cmd.summary) lines.push(cmd.description);
  if (cmd.destructive) lines.push("", "DESTRUCTIVE — requires --yes unless targeting localhost.");
  if (cmd.pathParams.length) {
    lines.push("", "path params (positional, in order):");
    lines.push(...cmd.pathParams.map((p) => `  <${p}>`));
  }
  if (cmd.query.length) {
    lines.push("", "query:");
    lines.push(...cmd.query.map(describeParam));
  }
  if (cmd.body.length) {
    lines.push("", `body (${cmd.bodyContentType ?? "application/json"}):`);
    lines.push(...cmd.body.map(describeParam));
  } else if (cmd.bodyContentType) {
    lines.push("", `body: ${cmd.bodyContentType} — pass with --data`);
  }
  if (cmd.responses?.length) {
    lines.push("", "responses:");
    lines.push(...cmd.responses.map((r) => `  ${r.code}  ${r.description}`));
  }
  lines.push("", "example:", `  kvn ${cmd.name}${cmd.pathParams.map((p) => ` <${p}>`).join("")}${exampleFlags(cmd)}`);
  out(lines.join("\n"));
}

function describeParam(p) {
  const bits = [`  --${p.name}`, `<${p.type}>`];
  if (p.required) bits.push("(required)");
  if (p.enum?.length) bits.push(`one of: ${p.enum.join(", ")}`);
  else if (p.description) bits.push(`— ${p.description}`);
  return bits.join(" ");
}

function exampleFlags(cmd) {
  const required = [...cmd.query, ...cmd.body].filter((p) => p.required).slice(0, 4);
  return required.map((p) => ` --${p.name} <${p.type}>`).join("");
}

// ── request ──────────────────────────────────────────────────────────────────

function resolveBase(globals) {
  if (globals.base) return globals.base.replace(/\/+$/, "");
  if (globals.local) return LOCAL_BASE;
  if (process.env.KAVANAH_BASE_URL) return process.env.KAVANAH_BASE_URL.replace(/\/+$/, "");
  return DEFAULT_BASE;
}

function isLocal(base) {
  return /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])(:|\/|$)/.test(base);
}

/**
 * Destructive gate for ad-hoc `kvn call` requests. Named commands carry a
 * `destructive` flag baked in by the generator; ad-hoc calls apply the SAME
 * path rules, which the generator emits into commands.json as
 * `destructiveRules` ({ pattern, methods? } — pattern is a regex source,
 * methods optionally restricts which verbs the rule covers). Method still
 * matters: DELETE is always destructive, GET/HEAD never are (an ad-hoc read
 * must not demand --yes), everything else consults the rules.
 */
function adhocDestructive(method, path) {
  if (method === "DELETE") return true;
  if (method === "GET" || method === "HEAD") return false;
  const pathname = path.split(/[?#]/)[0];
  return (index().destructiveRules ?? []).some(
    (rule) =>
      new RegExp(rule.pattern).test(pathname) && (!rule.methods || rule.methods.includes(method)),
  );
}

/**
 * Read stdin. `implicit` reads happen when no --data was given, and ONLY from a
 * redirected regular file (`kvn x < body.json`): a pipe or socket that the
 * caller never closes — which is how several agent harnesses spawn commands —
 * would otherwise block every command forever waiting for an EOF that never
 * comes. That was the "kvn tool hangs for 5 minutes" report. A pipe is read
 * only when asked for explicitly with `--data -`.
 */
async function readStdin({ implicit = false } = {}) {
  if (process.stdin.isTTY) return null;
  if (implicit) {
    try {
      if (!fstatSync(0).isFile()) return null;
    } catch {
      return null;
    }
  }
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  const text = Buffer.concat(chunks).toString("utf8").trim();
  return text || null;
}

async function resolveBody(globals) {
  let raw = globals.data;
  if (raw === "-") raw = await readStdin();
  else if (raw?.startsWith("@")) {
    const file = raw.slice(1);
    if (!existsSync(file)) die(`--data file not found: ${file}`);
    raw = readFileSync(file, "utf8");
  } else if (raw === undefined) {
    raw = await readStdin({ implicit: true });
  }
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (err) {
    die(`--data is not valid JSON: ${err.message}`);
  }
}

async function run(cmd, parsed) {
  const { positional, globals, fields, forcedQuery } = parsed;
  const base = resolveBase(globals);
  const key = requireKey(globals.key, base);

  if (cmd.destructive && !globals.yes && !globals.y && !isLocal(base)) {
    die(
      `${cmd.name} is destructive (${cmd.method} ${cmd.path}) and targets ${base}.\n` +
        `Re-run with --yes if that is intended, or --local to hit the dev server.`,
    );
  }

  // Path params come from positionals in declaration order; a --<param> flag
  // may name one explicitly and takes precedence.
  let pathname = cmd.path;
  const remaining = [...positional];
  for (const p of cmd.pathParams) {
    let value;
    if (fields.has(p)) {
      value = fields.get(p).raw;
      fields.delete(p);
    } else {
      value = remaining.shift();
    }
    if (value === undefined) {
      die(`${cmd.name} needs path param <${p}> — usage: kvn ${cmd.name} ${cmd.pathParams.map((x) => `<${x}>`).join(" ")}`);
    }
    pathname = pathname.replace(`{${p}}`, encodeURIComponent(String(value)));
  }
  if (remaining.length) die(`unexpected extra argument(s): ${remaining.join(" ")}`);

  // Field routing: declared query params → query; declared body fields → body;
  // undeclared → query for GET/DELETE, body otherwise (matches how the routes read them).
  const queryTypes = new Map(cmd.query.map((q) => [q.name, q.type]));
  const bodyTypes = new Map(cmd.body.map((b) => [b.name, b.type]));
  const queryNames = new Set(queryTypes.keys());
  const bodyNames = new Set(bodyTypes.keys());
  const url = new URL(base + pathname);
  const body = (await resolveBody(globals)) ?? {};
  let hasBody = Object.keys(body).length > 0;

  for (const [name, { raw }] of fields) {
    const toQuery = queryNames.has(name)
      ? true
      : bodyNames.has(name)
        ? false
        : cmd.method === "GET" || cmd.method === "DELETE";
    if (toQuery) {
      url.searchParams.set(name, raw);
    } else {
      assignDeep(body, name, coerceTyped(raw, bodyTypes.get(name)));
      hasBody = true;
    }
  }
  for (const [k, v] of forcedQuery) url.searchParams.set(k, v);

  const missing = [...cmd.query.filter((q) => q.required).map((q) => q.name)].filter(
    (n) => !url.searchParams.has(n),
  );
  if (missing.length) {
    process.stderr.write(`warning: missing required query param(s): ${missing.map((m) => `--${m}`).join(" ")}\n`);
  }

  const init = {
    method: cmd.method,
    headers: {
      Authorization: `Bearer ${key}`,
      Accept: "application/json",
      "User-Agent": "kvn-claude-code-skill",
    },
  };
  if (hasBody && cmd.method !== "GET") {
    init.headers["Content-Type"] = "application/json";
    init.body = JSON.stringify(body);
  }

  if (globals["dry-run"]) {
    return out(
      [
        `${cmd.method} ${url.toString()}`,
        `Authorization: Bearer ${key.slice(0, 12)}…`,
        init.body ? `\n${JSON.stringify(body, null, 2)}` : "(no body)",
      ].join("\n"),
    );
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  let res;
  try {
    res = await fetch(url, { ...init, signal: controller.signal, redirect: "manual" });
  } catch (err) {
    if (err.name === "AbortError") die(`request timed out after ${TIMEOUT_MS}ms: ${cmd.method} ${url}`);
    die(`request failed: ${err.message}${isLocal(base) ? " (is `npm run dev` running?)" : ""}`);
  } finally {
    clearTimeout(timer);
  }

  const text = await res.text();
  if (globals.include || globals.i) {
    process.stderr.write(`HTTP ${res.status} ${res.statusText}\n`);
    for (const [k, v] of res.headers) process.stderr.write(`${k}: ${v}\n`);
    process.stderr.write("\n");
  }

  if (globals.raw) out(text);
  else {
    try {
      out(JSON.stringify(JSON.parse(text), null, 2));
    } catch {
      out(text);
    }
  }

  if (!res.ok) {
    process.stderr.write(`\n✖ HTTP ${res.status} ${res.statusText} — ${cmd.method} ${url.pathname}\n`);
    if (res.status === 401) {
      process.stderr.write("  401 usually means the API key is revoked, or its user lost workspace membership.\n");
    }
    if (res.status === 403) {
      process.stderr.write("  403 means the key's user lacks the RBAC permission for this route (keys inherit user permissions).\n");
    }
    process.exit(1);
  }
}

// ── agent toolkit ────────────────────────────────────────────────────────────

/**
 * `kvn agent "<prompt>"` — reach the agent toolkit through the model. Posts to
 * POST /api/ai-agent, so persona scoping, guardrails, the action-policy
 * decision, the ledger and undo all apply. `kvn tool` (below) is the
 * deterministic alternative.
 */
async function cmdAgent(parsed) {
  const { positional, globals, fields } = parsed;
  const prompt = positional.join(" ").trim();
  if (!prompt) die('usage: kvn agent "<what you want the agent to do>" [--conversation <id>] [--persona <id>]');

  const base = resolveBase(globals);
  const key = requireKey(globals.key, base);

  const body = { messages: [{ role: "user", content: prompt }], stream: false };
  if (fields.has("conversation")) body.conversation_id = fields.get("conversation").raw;
  if (fields.has("persona")) body.persona_id = fields.get("persona").raw;

  if (globals["dry-run"]) {
    return out(`POST ${base}/api/ai-agent\n${JSON.stringify(body, null, 2)}`);
  }

  // The tool loop legitimately runs for minutes; the per-request default is far
  // too short for it, so the agent gets its own ceiling.
  const timeout = Number(process.env.KAVANAH_AGENT_TIMEOUT_MS ?? 300_000);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);
  let res;
  try {
    res = await fetch(`${base}/api/ai-agent`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
        Accept: "application/json",
        "User-Agent": "kvn-claude-code-skill",
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } catch (err) {
    if (err.name === "AbortError") {
      die(
        `agent run exceeded ${timeout}ms and the client gave up.\n` +
          "NOTE: this does NOT cancel the run — it may still be writing. Check with:\n" +
          "  kvn ai-agent.activity.list",
      );
    }
    die(`agent request failed: ${err.message}`);
  } finally {
    clearTimeout(timer);
  }

  const text = await res.text();
  if (!res.ok) {
    process.stderr.write(`✖ HTTP ${res.status} ${res.statusText} — POST /api/ai-agent\n`);
    out(text);
    process.exit(1);
  }

  let parsedBody;
  try {
    parsedBody = JSON.parse(text);
  } catch {
    return out(text);
  }
  if (globals.raw) return out(JSON.stringify(parsedBody, null, 2));

  // Surface the reply and what it actually did — a parked action is the thing a
  // caller most needs to notice, and it is easy to miss inside the full payload.
  const reply = parsedBody.message ?? parsedBody.content ?? parsedBody.reply ?? null;
  out(typeof reply === "string" ? reply : JSON.stringify(parsedBody, null, 2));
  if (parsedBody.conversation_id) {
    process.stderr.write(`\nconversation: ${parsedBody.conversation_id} (pass --conversation to continue it)\n`);
  }
  const parked = parsedBody.parked_actions ?? parsedBody.pending_approvals;
  if (Array.isArray(parked) && parked.length) {
    process.stderr.write(`${parked.length} action(s) parked for approval — see: kvn ai-agent.approvals.list\n`);
  }
}

/**
 * `kvn tool <name> [--field value]` — execute ONE agent tool deterministically.
 *
 * Unlike `kvn agent`, no model is involved: the named tool runs with the given
 * arguments. The server still applies the whole governance stack, so a policy
 * that requires approval PARKS the call (202) instead of running it — that is
 * not an error, and re-running will just park again.
 */
async function cmdTool(parsed) {
  const { positional, globals, fields } = parsed;
  const toolName = positional[0];
  if (!toolName) die('usage: kvn tool <tool_name> [--field value ...] [--persona <id>] [--run-id <id>]');

  const base = resolveBase(globals);
  const key = requireKey(globals.key, base);

  // Coerce against the tool's declared input_schema for the same reason the REST
  // path does: agent tools take numeric-looking STRINGS (project_ref, task ids
  // as strings in some tools), and a JSON number fails their validation.
  const declared = new Map();
  const toolsFile = join(SKILL_DIR, "agent-tools.json");
  if (existsSync(toolsFile)) {
    const entry = JSON.parse(readFileSync(toolsFile, "utf8")).tools.find((t) => t.name === toolName);
    for (const p of entry?.params ?? []) declared.set(p.name, p.type);
  }

  const input = (await resolveBody(globals)) ?? {};
  let personaId = null;
  let runId = null;
  for (const [name, { raw }] of fields) {
    if (name === "persona") personaId = raw;
    else if (name === "run-id") runId = raw;
    else assignDeep(input, name, coerceTyped(raw, declared.get(name)));
  }

  const body = { input };
  if (personaId) body.persona_id = personaId;
  if (runId) body.run_id = runId;
  const url = `${base}/api/ai-agent/tools/${encodeURIComponent(toolName)}/execute`;

  if (globals["dry-run"]) return out(`POST ${url}\n${JSON.stringify(body, null, 2)}`);

  const timeout = Number(process.env.KAVANAH_AGENT_TIMEOUT_MS ?? 300_000);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeout);
  let res;
  try {
    res = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
        Accept: "application/json",
        "User-Agent": "kvn-claude-code-skill",
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } catch (err) {
    if (err.name === "AbortError") {
      die(
        `tool run exceeded ${timeout}ms. This does NOT cancel it server-side.\n` +
          `Re-run with --run-id ${runId ?? "<same id>"} to make the retry idempotent.`,
      );
    }
    die(`tool request failed: ${err.message}`);
  } finally {
    clearTimeout(timer);
  }

  const text = await res.text();
  let payload;
  try {
    payload = JSON.parse(text);
  } catch {
    out(text);
    process.exit(res.ok ? 0 : 1);
  }

  if (globals.raw) return out(JSON.stringify(payload, null, 2));

  if (res.status === 202) {
    out(payload.message ?? "Parked for approval.");
    process.stderr.write(
      `\nPARKED (${payload.reason ?? "approval_required"}${payload.category ? `, ${payload.category}` : ""}) — nothing ran.\n` +
        `approval: ${payload.approval_id ?? "?"} — see: kvn ai-agent.approvals.list\n`,
    );
    process.exit(2);
  }
  if (!res.ok) {
    out(payload.message ?? payload.error ?? text);
    process.stderr.write(`\n✖ HTTP ${res.status} — ${payload.status ?? "error"}${payload.reason ? ` (${payload.reason})` : ""}\n`);
    if (res.status === 404) process.stderr.write("  The tool may exist but be outside your persona scope / action mode.\n");
    process.exit(1);
  }

  out(payload.content ?? JSON.stringify(payload, null, 2));
  if (payload.undo_group) {
    // POST /api/undo takes no arguments — it pops the caller's most recent
    // undoable group. The id is shown so you can confirm what would be reversed,
    // not to pass back.
    process.stderr.write(
      `\nundo: ${payload.undo_group.id} (${payload.undo_group.label})\n` +
        "  reverse it with: kvn undo.create   (undoes YOUR most recent group — run it before doing anything else undoable)\n",
    );
  }
}

/** `kvn tools [pattern]` — search the agent toolkit (names + descriptions). */
function cmdTools(pattern) {
  const file = join(SKILL_DIR, "agent-tools.json");
  if (!existsSync(file)) die("agent-tools.json missing — run 'npm run skill:gen' in the Kavanah repo");
  const { tools } = JSON.parse(readFileSync(file, "utf8"));
  let hits = tools;
  if (pattern) {
    let re = null;
    try {
      re = new RegExp(pattern, "i");
    } catch {
      re = null;
    }
    // Multi-word searches match all words anywhere ("log time" → log_time_entry),
    // not as one contiguous substring — nobody guesses the exact wording.
    const words = pattern.toLowerCase().split(/\s+/).filter(Boolean);
    hits = tools.filter((t) => {
      const hay = `${t.name} ${t.description} ${t.scope ?? ""}`;
      if (re?.test(t.name)) return true;
      const lowered = hay.toLowerCase().replace(/_/g, " ");
      return words.every((w) => lowered.includes(w));
    });
  }
  if (!hits.length) return out(`no agent tools match "${pattern}"`);
  const width = Math.max(...hits.map((t) => t.name.length));
  for (const t of hits) {
    out(`${t.name.padEnd(width)}  ${t.readOnly ? "read " : "write"}  ${t.description.slice(0, 110)}`);
  }
  process.stderr.write(
    `\n${hits.length} of ${tools.length} agent tools. Run one with: kvn tool <name> --field v   (or: kvn agent "<prompt>")\n`,
  );
}

// ── login / logout ───────────────────────────────────────────────────────────

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Best effort: a headless box, SSH session or sandbox simply prints the URL. */
function openBrowser(url) {
  const cmd =
    process.platform === "darwin" ? ["open", [url]]
    : process.platform === "win32" ? ["cmd", ["/c", "start", "", url]]
    : ["xdg-open", [url]];
  try {
    const child = spawn(cmd[0], cmd[1], { stdio: "ignore", detached: true });
    child.on("error", () => {});
    child.unref();
  } catch {
    // Printing the URL is the fallback, and it already happened.
  }
}

async function postJson(url, body) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json", "User-Agent": "kvn-claude-code-skill" },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  const payload = await res.json().catch(() => ({}));
  return { res, payload };
}

/**
 * `kvn login` — OAuth device authorization (RFC 8628) against
 * /api/auth/cli/{start,token}. The terminal shows a short code and opens
 * /cli/authorize; a workspace admin approves it while signed in, and the next
 * poll returns a fresh API key acting as that admin in the active workspace.
 * The key is saved per base URL in ~/.kavanah/credentials.json (mode 0600).
 */
async function cmdLogin(parsed) {
  const { globals, fields } = parsed;
  const base = resolveBase(globals);
  const clientName = fields.get("name")?.raw ?? `kvn on ${hostname()}`;

  let start;
  try {
    start = await postJson(`${base}/api/auth/cli/start`, { client_name: clientName });
  } catch (err) {
    die(`could not reach ${base}: ${err.message}${isLocal(base) ? " (is `npm run dev` running?)" : ""}`);
  }
  if (!start.res.ok || !start.payload.device_code) {
    die(`✖ ${base} refused to start a sign-in (HTTP ${start.res.status}): ${start.payload.error ?? "unknown error"}`);
  }
  const { device_code, user_code, verification_uri, verification_uri_complete, expires_in, interval } = start.payload;

  process.stderr.write(
    [
      "",
      `  To connect kvn to Kavanah (${base}), approve this code in your browser:`,
      "",
      `      ${user_code}`,
      "",
      `  ${verification_uri_complete}`,
      "",
      "  A workspace admin must approve it. The key acts as the approver, in the",
      "  workspace that is active in that browser session.",
      "",
    ].join("\n"),
  );
  if (!fields.has("no-browser")) openBrowser(verification_uri_complete ?? verification_uri);
  process.stderr.write("  Waiting for approval…");

  let wait = Math.max(1, Number(interval) || 3) * 1000;
  const deadline = Date.now() + (Number(expires_in) || 600) * 1000;
  while (Date.now() < deadline) {
    await sleep(wait);
    let poll;
    try {
      poll = await postJson(`${base}/api/auth/cli/token`, { device_code });
    } catch {
      continue; // a dropped poll is not a verdict; try again on the next tick
    }
    if (poll.res.ok && poll.payload.token) {
      const creds = readCredentials();
      creds[base] = {
        token: poll.payload.token,
        keyId: poll.payload.key?.id ?? null,
        keyName: poll.payload.key?.name ?? null,
        workspace: poll.payload.workspace ?? null,
        email: poll.payload.user?.email ?? null,
        savedAt: new Date().toISOString(),
      };
      writeCredentials(creds);
      process.stderr.write(" approved.\n\n");
      out(
        `Signed in to ${poll.payload.workspace?.name ?? "Kavanah"} as ${poll.payload.user?.email ?? "you"} (${base}).\n` +
          `Key saved to ${CREDENTIALS_FILE}. Revoke it with \`kvn logout\` or in Settings → API keys.`,
      );
      if (process.env.KAVANAH_API_KEY) {
        process.stderr.write("note: $KAVANAH_API_KEY is set and takes precedence over the saved key.\n");
      }
      return;
    }
    const code = poll.payload.error;
    if (code === "authorization_pending") continue;
    if (code === "slow_down") {
      wait += 5000;
      continue;
    }
    if (poll.res.status === 429) {
      wait += 5000;
      continue;
    }
    process.stderr.write("\n");
    if (code === "access_denied") die("✖ The request was denied in the browser. Nothing was created.");
    if (code === "expired_token") die("✖ The code expired before it was approved. Run `kvn login` again.");
    die(`✖ Sign-in failed (HTTP ${poll.res.status}): ${poll.payload.error_description ?? code ?? "unknown error"}`);
  }
  process.stderr.write("\n");
  die("✖ Timed out waiting for approval. Run `kvn login` again.");
}

/** `kvn logout` — revoke the saved key server-side (unless --keep-key) and forget it locally. */
async function cmdLogout(parsed) {
  const { globals, fields } = parsed;
  const base = resolveBase(globals);
  const creds = readCredentials();
  const entry = creds[base];
  if (!entry) die(`no saved login for ${base} (keys from $KAVANAH_API_KEY or ~/.kavanah/api-key are not touched).`);

  if (!fields.has("keep-key") && entry.keyId) {
    try {
      const res = await fetch(`${base}/api/settings/api-keys/${encodeURIComponent(entry.keyId)}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${entry.token}`, Accept: "application/json", "User-Agent": "kvn-claude-code-skill" },
        signal: AbortSignal.timeout(TIMEOUT_MS),
      });
      if (res.ok || res.status === 401) {
        process.stderr.write(res.ok ? "revoked the key on the server.\n" : "the key was already revoked.\n");
      } else {
        process.stderr.write(
          `warning: could not revoke the key (HTTP ${res.status}) — revoke "${entry.keyName ?? entry.keyId}" in Settings → API keys.\n`,
        );
      }
    } catch (err) {
      process.stderr.write(`warning: could not reach ${base} to revoke the key (${err.message}).\n`);
    }
  }
  delete creds[base];
  writeCredentials(creds);
  out(`Signed out of ${base}.`);
}

// ── entry ────────────────────────────────────────────────────────────────────

async function main() {
  const argv = process.argv.slice(2);
  if (!argv.length || argv[0] === "--help" || argv[0] === "-h") return cmdHelp();

  const [first, ...rest] = argv;

  if (first === "ls") return cmdLs(rest[0]);
  if (first === "groups") return cmdGroups();
  if (first === "help") return cmdHelp(rest[0]);

  const parsed = parseArgs(rest);

  if (first === "call") {
    const [method, path] = parsed.positional;
    if (!method || !path) die("usage: kvn call <METHOD> </api/path> [--field value]");
    const upperMethod = method.toUpperCase();
    const fullPath = path.startsWith("/") ? path : `/${path}`;
    return run(
      {
        name: `call ${method} ${path}`,
        method: upperMethod,
        path: fullPath,
        group: "ad-hoc",
        source: "ad-hoc",
        summary: "",
        destructive: adhocDestructive(upperMethod, fullPath),
        pathParams: [],
        query: [],
        body: [],
        responses: [],
      },
      { ...parsed, positional: [] },
    );
  }

  if (first === "login") return cmdLogin(parsed);
  if (first === "logout") return cmdLogout(parsed);
  if (first === "agent") return cmdAgent(parsed);
  if (first === "tool") return cmdTool(parsed);
  if (first === "tools") return cmdTools(parsed.positional[0]);

  if (first === "whoami") {
    return run(index().byName.get("profile.list") ?? { name: "whoami", method: "GET", path: "/api/profile", group: "Profile", source: "builtin", summary: "", destructive: false, pathParams: [], query: [], body: [], responses: [] }, parsed);
  }

  const cmd = index().byName.get(first);
  if (!cmd) {
    process.stderr.write(`unknown command "${first}". Closest matches:\n\n`);
    suggest(first);
    process.exit(1);
  }
  if (parsed.globals.help || parsed.globals.h) return cmdHelp(first);
  return run(cmd, parsed);
}

main().catch((err) => die(err?.stack ?? String(err)));
